# Questions 301-400: More Medium questions covering error recognition, indirect-to-direct, and mixed patterns
ALL.append(q(301,"Medium",'Which of the following is the correct indirect form of: "I am leaving now," he said.',["He said that he was leaving then.","He said that he is leaving now.","He said that I was leaving then.","He said that he was leaving now."],"He said that he was leaving then.","'Am leaving' → 'was leaving'; 'I' → 'he'; 'now' → 'then.'",["tense backshift","time expression","pronoun change"]))
ALL.append(q(302,"Medium",'Identify the ERROR in the indirect speech: He asked me where did I work.',["The error is retaining inverted word order. Correct: He asked me where I worked.","There is no error in this sentence.","The error is using 'me' instead of 'I.'","The error is using 'where' instead of 'if.'"],"The error is retaining inverted word order. Correct: He asked me where I worked.","In indirect questions, normal word order is required. 'Where did I work' should be 'where I worked.'",["error recognition","word order","wh-question"]))
ALL.append(q(303,"Medium",'Identify the ERROR: She said me that she was tired.',["The error is 'said me.' Correct: She told me that she was tired.","There is no error.","The error is 'was tired.' It should be 'is tired.'","The error is using 'that.' It should be removed."],"The error is 'said me.' Correct: She told me that she was tired.","'Said' cannot take a direct personal object. Use 'told' + person, or 'said to' + person.",["error recognition","reporting verb","grammar rule"]))
ALL.append(q(304,"Medium",'Identify the ERROR: He asked if was I ready.',["The error is inverted word order after 'if.' Correct: He asked if I was ready.","There is no error.","The error is using 'if.' It should be 'that.'","The error is 'was.' It should be 'am.'"],"The error is inverted word order after 'if.' Correct: He asked if I was ready.","After 'if/whether' in indirect questions, use normal word order: subject + verb.",["error recognition","word order","yes/no question"]))
ALL.append(q(305,"Medium",'Identify the ERROR: She told that she was leaving.',["The error is missing personal object after 'told.' Correct: She told me/him/them that she was leaving.","There is no error.","The error is 'was leaving.' It should be 'is leaving.'","The error is using 'that.' It should be removed."],"The error is missing personal object after 'told.' Correct: She told me/him/them that she was leaving.","'Told' requires a personal object (told someone). Without an object, use 'said.'",["error recognition","reporting verb","grammar rule"]))
ALL.append(q(306,"Medium",'Identify the ERROR: He asked where do I live.',["The error is retaining 'do' and inverted order. Correct: He asked where I lived.","There is no error.","The error is using 'where.' It should be 'if.'","The error is 'live.' It should be 'living.'"],"The error is retaining 'do' and inverted order. Correct: He asked where I lived.","In indirect questions, remove do/does/did and use normal word order with backshifted tense.",["error recognition","word order","auxiliary removal"]))
ALL.append(q(307,"Medium",'Identify the ERROR: She asked that I was coming to the party.',["The error is using 'that' for a yes/no question. Correct: She asked if I was coming to the party.","There is no error.","The error is 'was coming.' It should be 'am coming.'","The error is 'I.' It should be 'she.'"],"The error is using 'that' for a yes/no question. Correct: She asked if I was coming to the party.","Yes/no questions in indirect speech use 'if' or 'whether,' not 'that.'",["error recognition","conjunction","yes/no question"]))
ALL.append(q(308,"Medium",'Identify the ERROR: The teacher told the students that don\'t make noise.',["The error is using 'that don't make.' Commands use infinitive: The teacher told the students not to make noise.","There is no error.","The error is 'told.' It should be 'said.'","The error is 'students.' It should be 'student.'"],"The error is using 'that don't make.' Commands use infinitive: The teacher told the students not to make noise.","Indirect commands use: told + person + (not) to + base verb, not 'that + don't.'",["error recognition","command","infinitive structure"]))
ALL.append(q(309,"Medium",'Choose the correct form: The manager ___ that the meeting had been postponed.',["said","told","said to","told to"],"said","'Said' is correct when no personal object follows. 'Told' requires a personal object (told someone).",["reporting verb","grammar rule","usage"]))
