ALL.append(q(396,"Medium",'"Let us begin the meeting," the chairperson said.',["The chairperson suggested that they begin the meeting.","The chairperson said to let us begin the meeting.","The chairperson told that let them begin the meeting.","The chairperson said them to begin the meeting."],"The chairperson suggested that they begin the meeting.","'Let us' (suggestion) → suggested + that + subject + base verb; 'us' → 'they.'",["reporting verb","suggestion","subjunctive"]))
ALL.append(q(397,"Medium",'"What a shame that such talent is being wasted!" the critic exclaimed.',["The critic exclaimed that it was a shame that such talent was being wasted.","The critic exclaimed what a shame that such talent is being wasted.","The critic exclaimed that what a shame that such talent was being wasted.","The critic exclaimed that it is a shame that such talent is being wasted."],"The critic exclaimed that it was a shame that such talent was being wasted.","Exclamation → exclaimed + that + descriptive; 'is being wasted' → 'was being wasted.'",["exclamation","tense backshift","passive voice"]))
ALL.append(q(398,"Medium",'"Hurrah! We have won the championship!" the team captain shouted.',["The team captain shouted with joy that they had won the championship.","The team captain shouted that hurrah they have won the championship.","The team captain shouted that they won the championship.","The team captain shouted with joy that we have won the championship."],"The team captain shouted with joy that they had won the championship.","Exclamation with interjection: remove 'Hurrah'; use emotion verb; 'have won' → 'had won'; 'we' → 'they.'",["exclamation","tense backshift","reporting verb"]))
